input_comps = {
    2: [(1, 2), (1, 3), (2, 3)],  # range [2, 3]
    3: [(4, 4), (5, 4), (4, 5)],  # range [4, 5]
    5: [(2, 7), (3, 7), (2, 8), (3, 8)],  # range [7, 8]
    6: [(7, 1), (7, 2)],  # range [1, 2]
    8: [(7, 6)],  # range [6, 6]
}

output_comps = {
    2: [(1, 10), (1, 11), (2, 11)],
    3: [(4, 11), (5, 11), (4, 12)],
    5: [(2, 12), (3, 12)],
    6: [(7, 10), (7, 11)],
    8: [(7, 12)]
}

# Create mapping from input (r,c) to output (r,c)
input_to_output = {}
for color, comp in input_comps.items():
    out_comps = output_comps[color]
    for i, inp_pos in enumerate(comp):
        inp_to_output[inp_pos] = out_comps[i]

# Calculate shift for each input point to its output position
print("Shift calculations:")
shifts = {}
for (ir, ic), (or_, oc) in inp_to_output.items():
    shift = oc - ic
    key = ir  # use row as key
    if key not in shifts:
        shifts[key] = shift
    print(f"  row {ir}: {key} -> {shift}")

