def torch_row_const_shift(row):
    # Find rightmost among ALL non-background pixels
    non_zero_positions = [c for c, v in enumerate(row) if v != 0]
    if not non_zero_positions:
        return [0] * len(row)

    all_rightmost = max(non_zero_positions)
    shift = 12 - all_rightmost

    result = [0] * len(row)
    for c, v in enumerate(row):
        if v != 0:
            nc = c + shift
            result[nc] = v
    return result

